class MSWindow {
  constructor(title, html, buttons, width, height) {
    this.title = title;
    this.html = html;
    this.buttons = buttons;
    this.width = width;
    this.height = height;
    this.element = null;
    this.dragging = false;
    this.offsetX = 0;
    this.offsetY = 0;
    this.startX = 0;
    this.startY = 0;
  }

  createWindow() {
    this.element = document.createElement("div");
    this.element.className = "windows-open-window";
    this.element.style.width = this.width + "px";
    this.element.style.height = this.height + "px";

    const titleBar = document.createElement("div");
    titleBar.className = "window-title-bar";
    this.element.appendChild(titleBar);

    const icon = document.createElement("div");
    icon.className = "window-icon";
    titleBar.appendChild(icon);

    const title = document.createElement("div");
    title.className = "window-title";
    title.textContent = this.title;
    titleBar.appendChild(title);

    const czBtns = document.createElement("div");
    czBtns.className = "window-czbtns";
    titleBar.appendChild(czBtns);

    for (const button of this.buttons) {
      const btn = document.createElement("div");
      btn.className = `window-${button}`;
      czBtns.appendChild(btn);
      btn.addEventListener("click", () => {
        switch (button) {
          case "close":
            this.closeWindow();
            break;
          case "max-size":
            this.maximizeWindow();
            break;
          case "min-size":
            this.minimizeWindow();
            break;
          default:
            console.error(`Unknown button: ${button}`);
        }
      });
    }

    const content = document.createElement("div");
    content.className = "window-content";
    this.element.appendChild(content);

    const iframe = document.createElement("iframe");
    iframe.srcdoc = this.html;
    content.appendChild(iframe);

    document.body.appendChild(this.element);

    this.addDraggable();
  }

  addDraggable() {
    const drags = document.createElement("div");
    drags.className = "window-drags";
    this.element.appendChild(drags);

    const top = document.createElement("div");
    top.className = "window-drags-top";
    drags.appendChild(top);

    const left = document.createElement("div");
    left.className = "window-drags-left";
    drags.appendChild(left);

    const bottom = document.createElement("div");
    bottom.className = "window-drags-bottom";
    drags.appendChild(bottom);

    const right = document.createElement("div");
    right.className = "window-drags-right";
    drags.appendChild(right);

    const topLeft = document.createElement("div");
    topLeft.className = "window-drags-top-left";
    drags.appendChild(topLeft);

    const topRight = document.createElement("div");
    topRight.className = "window-drags-top-right";
    drags.appendChild(topRight);

    const bottomLeft = document.createElement("div");
    bottomLeft.className = "window-drags-bottom-left";
    drags.appendChild(bottomLeft);

    const bottomRight = document.createElement("div");
    bottomRight.className = "window-drags-bottom-right";
    drags.appendChild(bottomRight);

    drags.addEventListener("mousedown", (e) => {
      this.dragging = true;
      this.startX = e.clientX;
      this.startY = e.clientY;
      this.element.style.transition = "none";
    });

    document.addEventListener("mousemove", (e) => {
      if (this.dragging) {
        const deltaX = e.clientX - this.startX;
        const deltaY = e.clientY - this.startY;
        this.element.style.top = `${parseInt(this.element.style.top) + deltaY}px`;
        this.element.style.left = `${parseInt(this.element.style.left) + deltaX}px`;
        this.startX = e.clientX;
        this.startY = e.clientY;
      }
    });

    document.addEventListener("mouseup", () => {
      this.dragging = false;
      this.element.style.transition = "all 0.3s";
    });
  }

  closeWindow() {
    this.element.remove();
  }

  maximizeWindow() {
    this.element.style.width = "100%";
    this.element.style.height = "100%";
    this.element.style.top = "0";
    this.element.style.left = "0";
  }

  minimizeWindow() {
    this.element.style.width = "200px";
    this.element.style.height = "100px";
    this.element.style.top = "100px";
    this.element.style.left = "100px";
  }
}

